// 仅导入 align-report 中 missingTitles，单条一批提高成功率
import fs from "fs";
import path from "path";
import { spawnSync } from "child_process";

const BASE = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const REPORT = path.join(BASE, "out", "align-report.json");
const SRC = path.join(BASE, "out", "distilled-projects");
const API = "http://127.0.0.1:1933";
const GAP = 8000;

function loadMem(project, title) {
  const dir = path.join(SRC, project);
  for (const f of fs.readdirSync(dir).filter((x) => x.endsWith(".json"))) {
    const j = JSON.parse(fs.readFileSync(path.join(dir, f), "utf8"));
    for (const m of j.memories || []) {
      if (m.title === title) return m;
    }
  }
  return null;
}

function toText(m) {
  const lines = [
    `【记忆类型】${m.type}`,
    `【标题】${m.title}`,
    `【内容】${m.content}`,
  ];
  if (m.evidence) lines.push(`【验证证据】${m.evidence}`);
  if (m.files?.length) lines.push(`【涉及文件】${m.files.join(" ; ")}`);
  if (m.project) lines.push(`【所属项目】${m.project}`);
  if (m.sessionIds?.length) lines.push(`【来源会话ID】${m.sessionIds.join(", ")}`);
  if (m.baseline) lines.push(`【代码基线】${m.baseline}`);
  return lines.join("\n");
}

async function api(p, opt) {
  const r = await fetch(API + p, opt);
  const t = await r.text();
  if (!r.ok) throw new Error(`${p} → ${r.status} ${t.slice(0, 200)}`);
  return JSON.parse(t);
}

async function importOne(project, title) {
  const m = loadMem(project, title);
  if (!m) {
    console.log("SKIP not in source:", title.slice(0, 60));
    return false;
  }
  const sid = `mm-retry-${project}-${Date.now()}`.replace(/[\\/:*?"<>|\s]+/g, "_");
  const { task_id: tid } = await api(`/api/v1/sessions/${sid}/messages/batch`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ messages: [{ role: "user", content: toText(m) }] }),
  });
  await api(`/api/v1/sessions/${sid}/commit`, { method: "POST" });
  for (let k = 0; k < 120; k++) {
    await new Promise((r) => setTimeout(r, 5000));
    const j = await api(`/api/v1/tasks/${tid}`);
    const list = Array.isArray(j) ? j : Array.isArray(j.result) ? j.result : [j.result || j];
    const t = list.find((x) => x && x.task_id === tid) || {};
    if (!["completed", "failed", "error", "cancelled"].includes(t.status)) continue;
    const ex = t.result?.memories_extracted || {};
    const w = ex.memory_write || 0;
    const e = ex.memory_edit || 0;
    console.log(
      project,
      title.slice(0, 50),
      "→",
      t.status,
      `write:${w} edit:${e}`,
      `${Math.round(t.processing_seconds || 0)}s`
    );
    const ok = t.status === "completed" && (w > 0 || e > 0);
    if (ok) {
      const donePath = path.join(process.env.TEMP, `done-${project}.json`);
      const set = new Set(fs.existsSync(donePath) ? JSON.parse(fs.readFileSync(donePath, "utf8")) : []);
      set.add(title);
      fs.writeFileSync(donePath, JSON.stringify([...set], null, 1), "utf8");
    }
    return ok;
  }
  console.log("TIMEOUT", title.slice(0, 50));
  return false;
}

const report = JSON.parse(fs.readFileSync(REPORT, "utf8"));
let ok = 0;
let fail = 0;
for (const p of report.projects) {
  if (!p.missingTitles?.length) continue;
  console.log(`\n--- ${p.project} (${p.missingTitles.length}) ---`);
  for (const title of p.missingTitles) {
    const r = await importOne(p.project, title);
    if (r) ok++;
    else fail++;
    await new Promise((r) => setTimeout(r, GAP));
  }
}
console.log(`\nDone ok=${ok} fail=${fail}`);
spawnSync(process.execPath, [path.join(BASE, "scripts", "align-check.mjs")], { cwd: BASE, stdio: "inherit" });
process.exit(fail ? 1 : 0);

